import Foundation

/// Explicit navigation needs no provider, tools generated by a model, or document access.
@MainActor
enum SessionNavigation {
    static func command(_ input: String) -> String? {
        let text = input.trimmingCharacters(in: .whitespacesAndNewlines)
        guard text.count <= 2_000 else { return nil }
        if text == "/select_session" || text.hasPrefix("/select_session ") { return text }
        if text == "/sessions" { return "/select_session" }
        let prefix = #"^(?:(?:please|can you|could you)\s+)?"#
        if text.range(of: prefix + #"(?:show|list|what are|which are)\s+(?:me\s+)?(?:(?:my|the|available|saved)\s+)?sessions[.!?]?$"#,
                      options: [.regularExpression, .caseInsensitive]) != nil { return "/select_session" }
        let patterns = [
            prefix + #"(?:switch|change|select|open|use|go|move)(?:\s+(?:me|my))?(?:\s+to)?\s+(?:a\s+|the\s+|another\s+|different\s+)?sessions?(?:\s+(?:to|called|named))?(?:\s+(.+?))?[.!?]?$"#,
            prefix + #"(?:switch|change|go|move)\s+to\s+(.+?)(?:\s+session)[.!?]?$"#
        ]
        for pattern in patterns {
            guard let regex = try? NSRegularExpression(pattern: pattern, options: .caseInsensitive),
                  let match = regex.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)) else { continue }
            let target = Range(match.range(at: 1), in: text).map { String(text[$0]) } ?? ""
            return "/select_session" + (target.isEmpty ? "" : " " + target)
        }
        return nil
    }

    static func sessions(_ state: PetApplicationState) -> [SessionFolderRecord] {
        state.sessionFolders.values.sorted {
            let order = $0.title.localizedCaseInsensitiveCompare($1.title)
            return order == .orderedSame ? $0.id.uuidString < $1.id.uuidString : order == .orderedAscending
        }
    }
    static func clean(_ target: String) -> String {
        target.trimmingCharacters(in: .whitespacesAndNewlines.union(CharacterSet(charactersIn: "\"'“”")))
    }
    static func matching(_ target: String, state: PetApplicationState) -> [SessionFolderRecord] {
        let value = clean(target)
        let exact = sessions(state).filter { $0.title.caseInsensitiveCompare(value) == .orderedSame || $0.id.uuidString.caseInsensitiveCompare(value) == .orderedSame }
        if !exact.isEmpty { return exact }
        return Int(value) == nil ? [] : sessions(state).filter { $0.title.caseInsensitiveCompare("Session " + value) == .orderedSame }
    }
    static func choices(_ state: PetApplicationState, prefix: String = "Which session should I open?") -> String {
        let options = sessions(state).enumerated().map { index, session in
            "\(index + 1). \(session.title)" + (session.id == state.activeSessionID ? " (current)" : "")
        }
        return prefix + "\n" + options.joined(separator: "\n") + "\nReply with a name or number."
    }
}
